{"path":"geo/cache.py","content":""""A small memoize decorator with hit/miss counters."""
import functools

_UNCACHEABLE = object()


def _make_key(args, kwargs):
    """Build a hashable key combining positional and keyword arguments.

    Keyword arguments are order-independent. Returns _UNCACHEABLE when the
    arguments cannot be hashed.
    """
    try:
        key = (args, tuple(sorted(kwargs.items())))
        hash(key)
        return key
    except TypeError:
        return _UNCACHEABLE


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _make_key(args, kwargs)
        if key is not _UNCACHEABLE:
            if key in cache:
                stats["hits"] += 1
                return cache[key]
            stats["misses"] += 1
        result = fn(*args, **kwargs)
        if key is not _UNCACHEABLE:
            cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
